function bet(id,even=false){const n=Number($(id).value); if(!Number.isSafeInteger(n)||n<1||(even&&n%2)){alert(even?'Enter a positive even-numbered bet (blackjack pays 3:2).':'Enter a positive whole-number bet.');return 0} if(n>balance){alert('Not enough chips for that bet.');return 0}return n}
