const titles={blackjack:['BLACKJACK','Get closer to 21 than the dealer, without going over.'],roulette:['ROULETTE','Pick a bet and let the wheel decide your fate.'],slots:['777 SLOTS','Three reels, four symbols, and one lucky spin.']};let current='blackjack';
