const ruleText={blackjack:'<p>A fresh, shuffled 52-card deck is used each round. Get closer to 21 than the dealer without busting. Aces count as 1 or 11; face cards count as 10.</p><p>The dealer stands on all 17s. A natural blackjack pays 3:2; other wins pay 1:1. Equal totals push. Double doubles your bet, takes exactly one card, and stands. No splitting or insurance.</p>',roulette:'<p>European roulette uses numbers 0–36. Red, black, odd, even, 1–18 and 19–36 pay 1:1. A single number pays 35:1. Zero loses all outside bets.</p>',slots:'<p>Each reel independently chooses one of four equally likely symbols: 7, ◆, ★ and ●. Three matching symbols pay the shown multiplier of your total bet, including the original stake. All other combinations lose.</p><p>777 pays 30×; ◆◆◆ pays 16×; ★★★ pays 8×; ●●● pays 4×. The theoretical return is 90.625% per spin.</p>'}; $('rules').onclick=()=>{$('rules-title').textContent=titles[current][0];$('rules-content').innerHTML=ruleText[current];$('rules-dialog').showModal()}; $('close-rules').onclick=$('got-it').onclick=()=>$('rules-dialog').close();
