function renderBJ(hide){$('player-cards').innerHTML=player.length?player.map(card).join(''):'<div class="card placeholder">?</div><div class="card placeholder">?</div>';$('dealer-cards').innerHTML=dealer.length?dealer.map((c,i)=>hide&&i===1?'<div class="card back">✦</div>':card(c)).join(''):'<div class="card placeholder">?</div><div class="card placeholder">?</div>';$('player-score').textContent=player.length?'· '+score(player):'';$('dealer-score').textContent=dealer.length?(hide?'· ?':'· '+score(dealer)):''}
function setButtons(){$('deal').disabled=active;$('hit').disabled=!active;$('stand').disabled=!active;$('double').disabled=!active||player.length!==2||balance<stake}
