function dealerTurn(){if(!active)return;while(score(dealer)<17)dealer.push(deck.pop());let p=score(player),d=score(dealer);if(d>21||p>d)finish('YOU WIN! +'+fmt(stake),stake*2);else if(p===d)finish('PUSH — YOUR BET IS RETURNED',stake);else finish('DEALER WINS — BETTER LUCK NEXT TIME',0)}
$('deal').onclick=()=>{if(active||arcadeBusy)return;let b=bet('bj-bet',true);if(!b)return;stake=b;balance-=b;updateBalance();newDeck();player=[deck.pop()];dealer=[deck.pop()];player.push(deck.pop());dealer.push(deck.pop());active=true;let pn=score(player)===21,dn=score(dealer)===21;if(pn||dn){if(pn&&dn)finish('BOTH BLACKJACK — PUSH',stake);else if(pn)finish('BLACKJACK! +'+fmt(stake*1.5),stake*2.5);else finish('DEALER BLACKJACK · HAND ENDED · BET LOST '+fmt(stake)+' · DEAL AGAIN',0)}else{renderBJ(true);$('bj-message').textContent='HIT, STAND, OR DOUBLE';setButtons()}};
$('hit').onclick=()=>{if(!active)return;player.push(deck.pop());if(score(player)>21)finish('BUST — DEALER WINS',0);else if(score(player)===21)dealerTurn();else{renderBJ(true);setButtons()}};$('stand').onclick=dealerTurn;$('double').onclick=()=>{if(!active||player.length!==2||balance<stake)return;balance-=stake;stake*=2;updateBalance();player.push(deck.pop());if(score(player)>21)finish('BUST — DEALER WINS',0);else dealerTurn()};
const reds=new Set([1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36]);for(let i=0;i<=36;i++)$('r-number').add(new Option(i,i));$('r-type').onchange=()=>{$('number-wrap').hidden=$('r-type').value!=='number'};let history=[];
$('spin-wheel').onclick=()=>{let b=bet('r-bet');if(!b)return;balance-=b;let n=rand(37),type=$('r-type').value;let win=type==='number'?n===Number($('r-number').value):n!==0&&({red:reds.has(n),black:!reds.has(n),even:n%2===0,odd:n%2===1,low:n<=18,high:n>=19})[type];let profit=win?b*(type==='number'?35:1):0;if(win)balance+=b+profit;updateBalance();$('roulette-result').textContent=n;$('roulette-result').style.color=n===0?'#78c99f':reds.has(n)?'#ef7179':'#f5e5c7';$('roulette-message').textContent=(n===0?'GREEN':reds.has(n)?'RED':'BLACK')+' '+n+' · '+(win?'YOU WIN +'+fmt(profit):'NO WIN THIS TIME');history.unshift(n);history=history.slice(0,10);$('history').textContent=history.join('  ·  ')};
$('spin-slots').onclick=()=>{let b=bet('s-bet');if(!b)return;balance-=b;let symbols=['7','◆','★','●'],mult=[30,16,8,4],results=[rand(4),rand(4),rand(4)];document.querySelectorAll('.reel').forEach((e,i)=>e.textContent=symbols[results[i]]);let payout=results.every(x=>x===results[0])?b*mult[results[0]]:0;balance+=payout;updateBalance();$('slot-message').textContent=payout?'WINNER! '+fmt(payout)+' CHIPS RETURNED':'NO MATCH — TRY YOUR LUCK AGAIN'};
/* Arcade presentation: the result is drawn once, before the animation begins. */
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
let arcadeBusy=false;
function pause(ms){return new Promise(resolve=>setTimeout(resolve,reducedMotion.matches?0:ms))}
function lockArcade(locked){arcadeBusy=locked;$('spin-wheel').disabled=locked;$('spin-slots').disabled=locked;$('reset').disabled=locked;document.querySelectorAll('.roulette-controls input,.roulette-controls select,#s-bet').forEach(e=>e.disabled=locked);if(!locked&&typeof saveGame==='function')saveGame()}
