const oldFinish=finish;
finish=function(msg,payout){oldFinish(msg,payout);celebrate($('blackjack'),payout>stake?'result-win':'result-lose')};
const oldRender=renderBJ;
renderBJ=function(hide){oldRender(hide);document.querySelectorAll('#blackjack .card').forEach((el,i)=>{el.style.animationDelay=(i*65)+'ms'})};
