$('spin-wheel').onclick=async()=>{if(arcadeBusy)return;const b=bet('r-bet');if(!b)return;const n=rand(37),type=$('r-type').value,choice=Number($('r-number').value);const win=type==='number'?n===choice:n!==0&&({red:reds.has(n),black:!reds.has(n),even:n%2===0,odd:n%2===1,low:n<=18,high:n>=19})[type];const profit=win?b*(type==='number'?35:1):0;balance-=b;updateBalance();lockArcade(true);$('roulette-message').textContent='THE WHEEL IS SPINNING...';$('roulette-result').textContent='✦';const wheel=document.querySelector('.wheel');await animateRoulette(n);if(win)balance+=b+profit;updateBalance();$('roulette-result').textContent=n;$('roulette-result').style.color=n===0?'#78c99f':reds.has(n)?'#ef7179':'#f5e5c7';$('roulette-message').textContent=(n===0?'GREEN':reds.has(n)?'RED':'BLACK')+' '+n+' · '+(win?'YOU WIN +'+fmt(profit):'NO WIN THIS TIME');history.unshift(n);history=history.slice(0,10);$('history').textContent=history.join('  ·  ');celebrate($('roulette'),win?'result-win':'result-lose');lockArcade(false)};
$('spin-slots').onclick=async()=>{if(arcadeBusy)return;const b=bet('s-bet');if(!b)return;const symbols=['7','◆','★','●'],mult=[30,16,8,4],results=[rand(4),rand(4),rand(4)],reels=[...document.querySelectorAll('.reel')];const settledPayout=results.every(x=>x===results[0])?b*mult[results[0]]:0;beginPendingRound(balance-b+settledPayout,'slots');balance-=b;updateBalance();lockArcade(true);$('slot-message').textContent='GOOD LUCK!';const timers=reels.map((el,i)=>{el.classList.add('rolling');let tick=i;return setInterval(()=>{el.textContent=symbols[(tick++)%symbols.length]},80+i*10)});for(let i=0;i<3;i++){await pause(i===0?650:350);clearInterval(timers[i]);reels[i].classList.remove('rolling');reels[i].textContent=symbols[results[i]];reels[i].classList.add('landed');setTimeout(()=>reels[i].classList.remove('landed'),500)}const payout=settledPayout;balance+=payout;updateBalance();$('slot-message').textContent=payout?'WINNER! '+fmt(payout)+' CHIPS RETURNED':'NO MATCH — TRY YOUR LUCK AGAIN';celebrate($('slots'),payout?'result-win':'result-lose');lockArcade(false);completePendingRound()};
/* Title screen, persistent table state, and an original synth lounge loop. */
const SAVE_KEY='lucky7-save-v2';
function saveGame(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({balance,deck,player,dealer,stake,active,current,history,version:2}))}catch(e){console.warn('Unable to save game',e)}}
