let audioContext=null,musicTimer=null,musicStep=0,musicOn=false;const notes=[220,277.18,329.63,440,392,329.63,277.18,246.94,220,261.63,329.63,392,440,392,329.63,261.63,196,246.94,293.66,392,369.99,293.66,246.94,220,207.65,261.63,311.13,415.3,392,311.13,261.63,246.94];
