const betZones=new Map();
function refreshBetZone(gameId){const data=betZones.get(gameId);if(!data)return;const amount=Number(data.input.value);const valid=Number.isSafeInteger(amount)&&amount>=0;data.amount.textContent=valid?fmt(amount):'—';const locked=arcadeBusy||(gameId==='blackjack'&&active);data.zone.classList.toggle('bet-locked',locked);data.zone.setAttribute('aria-disabled',String(locked));data.clear.disabled=locked;data.picker.querySelectorAll('button').forEach(button=>{button.draggable=!locked;button.disabled=locked});data.stack.replaceChildren();if(valid&&amount>0){let remaining=amount;const values=[100,50,20,10];const parts=[];for(const denomination of values){while(remaining>=denomination&&parts.length<5){parts.push(denomination);remaining-=denomination}}if(remaining>0)parts.push(remaining);parts.slice(0,6).forEach((value,index)=>{const chip=document.createElement('span');chip.className='wager-chip chip-'+([10,20,50,100].includes(value)?value:'other');chip.textContent=fmt(value);chip.style.setProperty('--chip-index',index);data.stack.appendChild(chip)})}}
