for(const gameId of ['blackjack','roulette','slots']){const game=$(gameId),controls=game.querySelector('.controls'),picker=controls.querySelector('.chip-picker'),input=$(gameId==='blackjack'?'bj-bet':gameId==='roulette'?'r-bet':'s-bet');const zone=document.createElement('div');zone.className='bet-zone';zone.setAttribute('role','group');zone.setAttribute('aria-label','Betting area: drag chips here to add to your wager');zone.innerHTML='<div class="bet-zone-copy"><span>DROP CHIPS HERE</span><strong>◈ <b>0</b></strong></div><div class="wager-stack" aria-hidden="true"></div><button class="clear-bet" type="button" title="Clear wager">CLEAR</button>';controls.insertBefore(zone,picker);const data={zone,input,picker,amount:zone.querySelector('b'),stack:zone.querySelector('.wager-stack'),clear:zone.querySelector('.clear-bet')};betZones.set(gameId,data);data.clear.onclick=()=>{if(arcadeBusy||(gameId==='blackjack'&&active))return;input.value='0';refreshBetZone(gameId)};input.addEventListener('input',()=>refreshBetZone(gameId));picker.querySelectorAll('button').forEach(button=>{button.draggable=true;button.setAttribute('aria-label','Bet '+button.dataset.chip+' chips; drag to add');button.addEventListener('click',()=>setTimeout(()=>refreshBetZone(gameId),0));button.addEventListener('dragstart',event=>{if(arcadeBusy||(gameId==='blackjack'&&active)){event.preventDefault();return}event.dataTransfer.effectAllowed='copy';event.dataTransfer.setData('text/plain','lucky7-chip:'+button.dataset.chip);button.classList.add('chip-dragging')});button.addEventListener('dragend',()=>{button.classList.remove('chip-dragging');zone.classList.remove('drag-over')})});zone.addEventListener('dragover',event=>{if(arcadeBusy||(gameId==='blackjack'&&active))return;event.preventDefault();event.dataTransfer.dropEffect='copy';zone.classList.add('drag-over')});zone.addEventListener('dragleave',event=>{if(!zone.contains(event.relatedTarget))zone.classList.remove('drag-over')});zone.addEventListener('drop',event=>{event.preventDefault();zone.classList.remove('drag-over');if(arcadeBusy||(gameId==='blackjack'&&active))return;const raw=event.dataTransfer.getData('text/plain');if(!/^lucky7-chip:(10|20|50|100)$/.test(raw))return;const denomination=Number(raw.split(':')[1]),prior=Number(input.value),next=(Number.isSafeInteger(prior)&&prior>=0?prior:0)+denomination;if(!Number.isSafeInteger(next))return;input.value=String(next);refreshBetZone(gameId);zone.classList.remove('chip-drop');void zone.offsetWidth;zone.classList.add('chip-drop')});refreshBetZone(gameId)}
