const autoPanel=document.createElement('section');autoPanel.className='auto-panel';autoPanel.innerHTML='<div class="auto-heading"><span>✦ AUTO PLAY</span><small id="auto-status" aria-live="polite">Blackjack auto: hit below 17; stand on 17.</small></div><label>ROUNDS <input id="auto-rounds" type="number" min="1" max="1000" value="10"></label><label class="auto-check"><input id="auto-win" type="checkbox"> STOP ON WIN</label><button id="auto-start" class="auto-button">START AUTO</button><button id="auto-stop" class="auto-button auto-stop" disabled>STOP</button>';document.querySelector('.game-panel').insertBefore(autoPanel,document.querySelector('.bottom-line'));
let autoRunning=false,autoCancel=false,autoGame=null,autoToken=0;
const manualIds=['deal','hit','stand','double','spin-wheel','spin-slots'];
function autoStatus(message){$('auto-status').textContent=message}
function setAutoState(running){autoRunning=running;$('auto-start').disabled=running;$('auto-stop').disabled=!running;$('auto-rounds').disabled=running;$('auto-win').disabled=running;document.querySelectorAll('.bet-zone input,.bet-zone button,.chip-picker button,.bet-control input,.bet-control select').forEach(el=>el.disabled=running||arcadeBusy);if(!running){setButtons();refreshAllBetZones()}}
