function reconcileCards(container,cards,hide){const visible=cards.length?cards.map((c,i)=>({key:hide&&i===1?'hidden':c.r+c.s,card:c,hidden:hide&&i===1})):[{key:'empty-1',empty:true},{key:'empty-2',empty:true}];while(container.children.length>visible.length)container.lastElementChild.remove();visible.forEach((item,i)=>{let existing=container.children[i];if(existing&&existing.dataset.cardKey===item.key)return;const holder=document.createElement('div');holder.innerHTML=item.empty?'<div class="card placeholder">?</div>':item.hidden?'<div class="card back">✦</div>':card(item.card);const fresh=holder.firstElementChild;fresh.dataset.cardKey=item.key;if(!item.empty){fresh.classList.add(existing&&existing.dataset.cardKey==='hidden'?'card-reveal':'card-arrive');fresh.style.animationDelay=(Math.min(i,4)*65)+'ms'}if(existing)existing.replaceWith(fresh);else container.appendChild(fresh)})}
