function rouletteWin(key,n){if(key.startsWith('n:'))return Number(key.slice(2))===n;if(n===0)return false;if(key==='red')return reds.has(n);if(key==='black')return !reds.has(n);if(key==='even')return n%2===0;if(key==='odd')return n%2===1;if(key==='low')return n<=18;if(key==='high')return n>=19;if(key==='dozen1')return n<=12;if(key==='dozen2')return n>=13&&n<=24;if(key==='dozen3')return n>=25;if(key==='col1')return n%3===1;if(key==='col2')return n%3===2;if(key==='col3')return n%3===0;return false}
