function placeRouletteChip(key,value){if(arcadeBusy||autoRunning)return;const total=boardStake(),next=total+value;if(!Number.isSafeInteger(next)||next>balance){$('board-feedback').textContent='Not enough chips for that bet.';return}rouletteBets.set(key,(rouletteBets.get(key)||0)+value);boardHistory.push({key,value});$('board-feedback').textContent='Bet placed · '+fmt(next)+' chips on the table.';renderRouletteBoard()}
$('board-undo').onclick=()=>{if(arcadeBusy||autoRunning||!boardHistory.length)return;const last=boardHistory.pop(),remaining=rouletteBets.get(last.key)-last.value;if(remaining)rouletteBets.set(last.key,remaining);else rouletteBets.delete(last.key);$('board-feedback').textContent='Last chip removed.';renderRouletteBoard()};$('board-clear').onclick=()=>{if(arcadeBusy||autoRunning)return;rouletteBets.clear();boardHistory.length=0;$('board-feedback').textContent='Table cleared. Select a chip to place a bet.';renderRouletteBoard()};
