$('spin-wheel').onclick=async()=>{if(arcadeBusy)return;const stake=boardStake();if(!stake){$('board-feedback').textContent='Place at least one chip on the roulette board.';return}if(stake>balance){$('board-feedback').textContent='Your total bet exceeds your chip balance.';return}const n=rand(37),bets=[...rouletteBets.entries()];const settledReturns=bets.reduce((sum,[key,amount])=>sum+(rouletteWin(key,n)?amount*rouletteMultiplier(key):0),0);beginPendingRound(balance-stake+settledReturns,'roulette');balance-=stake;updateBalance();lockArcade(true);renderRouletteBoard();$('roulette-message').textContent='THE WHEEL IS SPINNING...';$('roulette-result').textContent='✦';const wheel=document.querySelector('.wheel');await animateRoulette(n);const returns=settledReturns;balance+=returns;updateBalance();$('roulette-result').textContent=n;$('roulette-result').style.color=n===0?'#78c99f':reds.has(n)?'#ef7179':'#f5e5c7';const profit=returns-stake;$('roulette-message').textContent=(n===0?'GREEN':reds.has(n)?'RED':'BLACK')+' '+n+' · '+(profit>0?'YOU WIN +'+fmt(profit):profit===0?'PUSH':'NET −'+fmt(-profit));$('board-feedback').textContent=returns?'Returned '+fmt(returns)+' chips · '+(profit>0?'net win '+fmt(profit):profit===0?'bets break even':'net loss '+fmt(-profit))+'.':'No winning bets this spin.';history.unshift(n);history=history.slice(0,10);$('history').textContent=history.join('  ·  ');rouletteGrid.querySelectorAll('.roulette-spot').forEach(spot=>{spot.classList.toggle('winning-spot',rouletteWin(spot.dataset.bet,n)&&rouletteBets.has(spot.dataset.bet))});celebrate($('roulette'),profit>0?'result-win':'result-lose');lockArcade(false);completePendingRound();renderRouletteBoard()};
