/* Detailed, single-zero pixel wheel texture shared by table and result display. */
const wheelOrder=[0,32,15,19,4,21,2,25,17,34,6,27,13,36,11,30,8,23,10,5,24,16,33,1,20,14,31,9,22,18,29,7,28,12,35,3,26];
function createWheelTexture(){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const x=128,y=128;c.fillStyle='#30121c';c.beginPath();c.arc(x,y,125,0,Math.PI*2);c.fill();c.strokeStyle='#f6c36d';c.lineWidth=5;c.stroke();c.beginPath();c.arc(x,y,116,0,Math.PI*2);c.strokeStyle='#8c4d2d';c.lineWidth=5;c.stroke();const step=Math.PI*2/37;wheelOrder.forEach((n,i)=>{const start=-Math.PI/2+i*step,end=start+step;c.beginPath();c.moveTo(x,y);c.arc(x,y,111,start,end);c.closePath();c.fillStyle=n===0?'#16845d':reds.has(n)?'#b32c3a':'#17171d';c.fill();c.strokeStyle='#d4a55e';c.lineWidth=1;c.stroke();c.save();c.translate(x,y);c.rotate(start+step/2+Math.PI/2);c.fillStyle='#fff3cb';c.font='bold 7px monospace';c.textAlign='center';c.fillText(String(n),0,-100);c.restore()});for(const [radius,color] of [[78,'#d39d4a'],[74,'#4b201e'],[68,'#e6b75e'],[64,'#632b25'],[45,'#d19b4d'],[40,'#34151e']]){c.fillStyle=color;c.beginPath();c.arc(x,y,radius,0,Math.PI*2);c.fill()}c.strokeStyle='#f9d78b';c.lineWidth=2;c.beginPath();c.arc(x,y,55,0,Math.PI*2);c.stroke();c.fillStyle='#ffde93';c.beginPath();c.arc(x,y,9,0,Math.PI*2);c.fill();return canvas.toDataURL('image/png')}
const wheelTexture=createWheelTexture();const gameWheel=document.querySelector('.wheel');gameWheel.style.setProperty('--wheel-art','url("'+wheelTexture+'")');const tableWheel=document.createElement('div');tableWheel.className='scene-wheel-overlay';tableWheel.setAttribute('aria-hidden','true');tableWheel.innerHTML='<div class="scene-wheel-disc"></div><div class="scene-wheel-ball"></div>';$('roulette').querySelector('.scene').appendChild(tableWheel);tableWheel.querySelector('.scene-wheel-disc').style.setProperty('--wheel-art','url("'+wheelTexture+'")');new MutationObserver(()=>tableWheel.classList.toggle('wheel-active',gameWheel.classList.contains('spinning'))).observe(gameWheel,{attributes:true,attributeFilter:['class']});
/* A 32-frame celebratory cutscene plays after a winning round. */
const danceImage=new Image();danceImage.src='win-dance-32.png';let danceOverlay=null,dancePromise=null,danceResolve=null,danceFrame=0,danceStart=0;
function endDance(){if(!danceOverlay)return;cancelAnimationFrame(danceFrame);danceOverlay.remove();danceOverlay=null;const done=danceResolve;danceResolve=null;dancePromise=null;if(done)done()}
function playWinDance(){if(motionOff||reducedMotion.matches)return;if(danceOverlay)endDance();dancePromise=new Promise(resolve=>{danceResolve=resolve});danceOverlay=document.createElement('div');danceOverlay.className='win-cutscene';danceOverlay.innerHTML='<div class="win-cutscene-panel"><div class="win-cutscene-title">✦ &nbsp; WINNER! &nbsp; ✦</div><canvas width="192" height="256" aria-label="Pixel art victory dance"></canvas><div class="win-cutscene-sub">LUCK IS ON YOUR SIDE</div><button type="button" class="win-cutscene-skip">SKIP ▶</button></div>';document.body.appendChild(danceOverlay);danceOverlay.querySelector('button').onclick=endDance;const canvas=danceOverlay.querySelector('canvas'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;danceStart=performance.now();function draw(now){if(!danceOverlay)return;const elapsed=now-danceStart;if(elapsed>=6000){endDance();return}if(danceImage.complete&&danceImage.naturalWidth){const sequence=[0,1,2,3,4,5,6,5,4,3,2,1];const progress=elapsed/6000*sequence.length;const index=Math.floor(progress);const frame=sequence[index],next=sequence[(index+1)%sequence.length];const w=danceImage.naturalWidth/8,h=danceImage.naturalHeight/4;const blend=Math.max(0,(progress-index-.7)/.3);ctx.clearRect(0,0,192,256);ctx.globalAlpha=1;ctx.drawImage(danceImage,(frame%8)*w,Math.floor(frame/8)*h,w,h,0,0,192,256);if(blend>0){ctx.globalAlpha=blend;ctx.drawImage(danceImage,(next%8)*w,Math.floor(next/8)*h,w,h,0,0,192,256);ctx.globalAlpha=1}}danceFrame=requestAnimationFrame(draw)}danceFrame=requestAnimationFrame(draw)}
