/* Skippable illustrated opening: voice starts only after the player's click. */
const opening=document.createElement('div');opening.className='opening';opening.innerHTML='<div class="opening-panel"><div class="opening-caption">✦ &nbsp; MEET YOUR HOST &nbsp; ✦</div><div class="host-portrait"><div class="host-eyes"><i></i><i></i></div><div class="host-mouth"></div><div class="host-jaw"></div></div><div class="host-line" aria-live="polite">MUAHAHA! WELCOME TO MY CASINO!</div><div class="opening-actions"><button id="opening-play" class="primary">PLAY INTRO ▶</button><button id="opening-skip" class="title-secondary">SKIP INTRO</button></div></div>';document.body.appendChild(opening);let openingTimer=null,openingFinished=false,openingVoiceStarted=false;function finishOpening(){if(openingFinished)return;openingFinished=true;clearTimeout(openingTimer);if('speechSynthesis' in window)window.speechSynthesis.cancel();opening.remove();if(typeof showAttendant==='function'){introduced.add(current);showAttendant(current,true)}}$('opening-skip').onclick=finishOpening;$('opening-play').onclick=()=>{if(opening.classList.contains('speaking'))return;opening.classList.add('speaking');$('opening-play').disabled=true;openingTimer=setTimeout(finishOpening,10500);if('speechSynthesis' in window){try{const voice=new SpeechSynthesisUtterance("Brendan, Jared, I thought you'd never come... Welcome to my casino.");voice.rate=.84;voice.pitch=.7;voice.onstart=()=>{openingVoiceStarted=true};voice.onend=()=>{clearTimeout(openingTimer);openingTimer=setTimeout(finishOpening,Math.max(700,6500-(performance.now()-window.openingSpeechStarted)))};window.speechSynthesis.speak(voice)}catch(e){console.warn('Intro voice unavailable',e)}}};

/* Host dialogue appears as a pixel-art speech box during the intro. */
