opening.addEventListener('pointerdown',event=>{if(openingFinished||openingVoiceStarted||event.target.closest('#opening-skip')||!('speechSynthesis' in window))return;try{window.speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance("Brendan, Jared, I thought you'd never come... Welcome to my casino.");voice.rate=.84;voice.pitch=.7;voice.onstart=()=>{openingVoiceStarted=true};window.speechSynthesis.speak(voice)}catch(e){console.warn('Intro speech unavailable',e)}},{once:true});
/* Introductions are tied to each table and replayable on request. */
const attendantLines={blackjack:{name:'ALYSSA',text:"Hi! I'm Alyssa, Mitchell's ex. They used to call me Horse Face in high school. We love Mitchell; we're Mitchell's Angels!"},roulette:{name:'MIKAYLA',text:"I'm Mitchell's ex too. I sure miss him, and wish I would've let him knock me up!"},slots:{name:'REBECCA',text:"I'm also Mitchell's ex. He has me on slot machine duty tonight, oh bummer!"}};
const attendantBox=document.createElement('div');attendantBox.className='attendant-dialogue';attendantBox.innerHTML='<div><span class="attendant-name"></span><p class="attendant-text"></p></div><button type="button" class="attendant-replay" aria-label="Replay introduction">♫ REPLAY</button>';document.querySelector('.panel-heading').after(attendantBox);const introduced=new Set();let introVoice=null;
function showAttendant(id,speak=false){const character=attendantLines[id];if(!character)return;attendantBox.querySelector('.attendant-name').textContent=character.name;attendantBox.querySelector('.attendant-text').textContent=character.text;if(speak&&openingFinished&&'speechSynthesis' in window){try{window.speechSynthesis.cancel();introVoice=new SpeechSynthesisUtterance(character.text);introVoice.rate=.93;introVoice.pitch=1.15;const voices=window.speechSynthesis.getVoices();const chosen=voices.find(v=>/female|zira|samantha|jenny|aria/i.test(v.name)&&/^en/i.test(v.lang));if(chosen)introVoice.voice=chosen;window.speechSynthesis.speak(introVoice)}catch(error){console.warn('Voice unavailable',error)}}}
attendantBox.querySelector('button').onclick=()=>showAttendant(current,true);document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{const id=tab.dataset.game,first=!introduced.has(id);if(openingFinished)introduced.add(id);showAttendant(id,first)}));for(const id of ['continue-game','new-game']){const button=$(id);if(button)button.addEventListener('click',()=>{showAttendant(current,false)})}showAttendant(current,false);


