/* Double all placed roulette bets when the balance permits. */
const doubleBoard=document.createElement('button');doubleBoard.type='button';doubleBoard.id='board-double';doubleBoard.textContent='2× BET';doubleBoard.title='Double the chips on every occupied spot';$('board-clear').before(doubleBoard);doubleBoard.onclick=()=>{if(arcadeBusy||autoRunning)return;const total=boardStake();if(!total){$('board-feedback').textContent='Place a bet before doubling.';return}if(total*2>balance||!Number.isSafeInteger(total*2)){$('board-feedback').textContent='Not enough chips to double the table.';return}for(const [key,amount] of [...rouletteBets]){rouletteBets.set(key,amount*2);boardHistory.push({key,value:amount})}renderRouletteBoard();$('board-feedback').textContent='All table bets doubled.'};

/* Single split: same rank, double after split, one card per split ace. */
let splitRound=null;const splitButton=document.createElement('button');splitButton.id='split';splitButton.textContent='SPLIT';splitButton.disabled=true;$('blackjack').querySelector('.actions').appendChild(splitButton);const splitStatus=document.createElement('div');splitStatus.className='split-status';splitStatus.hidden=true;document.querySelector('.score-panel').after(splitStatus);
function splitEligible(){return active&&!splitRound&&player.length===2&&player[0].r===player[1].r&&balance>=stake&&!autoRunning}
function syncSplit(){splitButton.disabled=!splitEligible();splitStatus.hidden=!splitRound;if(splitRound)splitStatus.textContent=splitRound.hands.map((h,i)=>(i===splitRound.index?'▶ ':'')+'HAND '+(i+1)+': '+score(h.cards)+(score(h.cards)>21?' BUST':'')+' · BET '+fmt(h.wager)).join('     |     ')}
const splitOldButtons=setButtons;setButtons=function(){splitOldButtons();syncSplit()};const splitOldRender=renderBJ;renderBJ=function(hide){splitOldRender(hide);syncSplit()};
const splitOldSave=saveGame;saveGame=function(){splitOldSave();try{if(splitRound&&active)localStorage.setItem('lucky7-split-v1',JSON.stringify(splitRound));else localStorage.removeItem('lucky7-split-v1')}catch(e){console.warn('Split save unavailable',e)}};
function splitSettle(){const hands=splitRound.hands;if(hands.some(h=>score(h.cards)<=21))while(score(dealer)<17)dealer.push(deck.pop());const d=score(dealer);let returned=0,total=0,results=[];for(const [i,h] of hands.entries()){const p=score(h.cards);total+=h.wager;if(p>21)results.push('HAND '+(i+1)+' BUST');else if(d>21||p>d){returned+=2*h.wager;results.push('HAND '+(i+1)+' WINS')}else if(p===d){returned+=h.wager;results.push('HAND '+(i+1)+' PUSH')}else results.push('HAND '+(i+1)+' LOSES')}active=false;balance+=returned;splitRound=null;updateBalance();renderBJ(false);$('bj-message').textContent=results.join(' · ');setButtons();celebrate($('blackjack'),returned>total?'result-win':'result-lose');saveGame()}
function nextSplitHand(){if(splitRound.index===0){splitRound.index=1;player=splitRound.hands[1].cards;stake=splitRound.hands[1].wager;if(score(player)===21){splitSettle();return}renderBJ(true);$('bj-message').textContent='PLAY HAND 2';setButtons();saveGame()}else splitSettle()}
splitButton.onclick=()=>{if(!splitEligible())return;const original=player,wager=stake;balance-=wager;splitRound={index:0,hands:[{cards:[original[0],deck.pop()],wager},{cards:[original[1],deck.pop()],wager}]};player=splitRound.hands[0].cards;stake=wager;updateBalance();if(original[0].r==='A'){splitSettle();return}if(score(player)===21){nextSplitHand();return}renderBJ(true);$('bj-message').textContent='PLAY HAND 1';setButtons();saveGame()};
const plainHit=$('hit').onclick,plainStand=$('stand').onclick,plainDouble=$('double').onclick,plainDeal=$('deal').onclick;
$('deal').onclick=function(){if(active||arcadeBusy)return;splitRound=null;return plainDeal.call(this)};$('hit').onclick=function(){if(!active)return;if(!splitRound)return plainHit.call(this);player.push(deck.pop());if(score(player)>=21)nextSplitHand();else{renderBJ(true);setButtons();saveGame()}};$('stand').onclick=function(){if(!active)return;if(!splitRound)return plainStand.call(this);nextSplitHand()};$('double').onclick=function(){if(!active)return;if(!splitRound)return plainDouble.call(this);if(player.length!==2||balance<stake)return;balance-=stake;stake*=2;splitRound.hands[splitRound.index].wager=stake;updateBalance();player.push(deck.pop());nextSplitHand()};
try{const savedSplit=JSON.parse(localStorage.getItem('lucky7-split-v1')||'null');if(active&&savedSplit&&Array.isArray(savedSplit.hands)&&savedSplit.hands.length===2&&[0,1].includes(savedSplit.index)&&savedSplit.hands.every(h=>Array.isArray(h.cards)&&Number.isSafeInteger(h.wager)&&h.wager>0)){splitRound=savedSplit;player=splitRound.hands[splitRound.index].cards;stake=splitRound.hands[splitRound.index].wager;renderBJ(true);setButtons()}}catch(e){console.warn('Split hand could not be restored',e)}
$('reset').addEventListener('click',()=>{if(!active){splitRound=null;saveGame();syncSplit()}});
ruleText.blackjack='<p>One freshly shuffled 52-card deck per round. Dealer stands on soft 17. Aces count as 1 or 11, face cards as 10. Natural blackjack pays 3:2; ordinary wins pay 1:1 and ties push.</p><p>Split matching ranks once into two hands with an equal additional wager. Double is allowed on either two-card split hand. Split aces receive exactly one card each. A 21 after splitting is an ordinary 21, not a natural blackjack. No resplits, insurance or surrender.</p><p>Auto play hits below 17 and stands on 17 or more; it does not split or double.</p>';


/* Phaser renders the victory sprite sheet. Game outcomes remain in the rules engine. */
let phaserVictory=null,phaserVictoryTimeout=null;const oldEndDance=endDance;endDance=function(){clearTimeout(phaserVictoryTimeout);if(phaserVictory){phaserVictory.destroy(true);phaserVictory=null}oldEndDance()};
playWinDance=function(){if(motionOff||reducedMotion.matches||!danceImage.complete||!danceImage.naturalWidth)return;if(danceOverlay)endDance();if(typeof Phaser==='undefined'){console.warn('Phaser unavailable; victory animation skipped');return}dancePromise=new Promise(resolve=>{danceResolve=resolve});danceOverlay=document.createElement('div');danceOverlay.className='win-cutscene';danceOverlay.innerHTML='<div class="win-cutscene-panel"><div class="win-cutscene-title">✦ &nbsp; WINNER! &nbsp; ✦</div><div class="phaser-victory-stage" aria-label="Pixel art victory dance"></div><div class="win-cutscene-sub">LUCK IS ON YOUR SIDE</div><button type="button" class="win-cutscene-skip">SKIP ▶</button></div>';document.body.appendChild(danceOverlay);danceOverlay.querySelector('button').onclick=endDance;const stage=danceOverlay.querySelector('.phaser-victory-stage');phaserVictoryTimeout=setTimeout(endDance,8500);phaserVictory=new Phaser.Game({type:Phaser.CANVAS,width:192,height:256,parent:stage,transparent:true,pixelArt:true,banner:false,audio:{noAudio:true},scene:{create(){if(!danceImage.complete||!danceImage.naturalWidth){endDance();return}this.textures.addSpriteSheet('victory',danceImage,{frameWidth:danceImage.naturalWidth/8,frameHeight:danceImage.naturalHeight/4});const sequence=[0,1,2,3,4,5,6,5,4,3,2,1];this.anims.create({key:'victory-loop',frames:sequence.map(frame=>({key:'victory',frame})),frameRate:2,repeat:0});const sprite=this.add.sprite(96,128,'victory',0).setDisplaySize(192,256);sprite.play('victory-loop');sprite.once('animationcomplete',endDance)}}})};
